    //! [maxBatchSize, maxNumPaths, maxPathLength]
    runtime::SizeType32* outputLastDraftIndices{nullptr};
    //! [maxBatchSize]
    T* randDataSample{nullptr};
    //! [maxBatchSize, maxNumPaths, maxPathDraftLength]
